package com.example.Hospital.Management.System.controllers; import com.example.Hospital.Management.System.dtos.*; import com.example.Hospital.Management.System.services.*; import jakarta.validation.Valid; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.*; @RestController @RequestMapping("/hospital") public class HospitalController{private final HospitalService s;public HospitalController(HospitalService s){this.s=s;}@PostMapping public ResponseEntity<HospitalDTO> create(@Valid @RequestBody HospitalDTO d){return ResponseEntity.status(201).body(s.create(d));}@GetMapping public List<HospitalDTO> all(){return s.all();}@GetMapping("/{id}") public HospitalDTO get(@PathVariable Long id){return s.get(id);}@PutMapping("/{id}") public HospitalDTO update(@PathVariable Long id,@Valid @RequestBody HospitalDTO d){return s.update(id,d);}@DeleteMapping("/{id}") public ResponseEntity<Void> delete(@PathVariable Long id){s.delete(id);return ResponseEntity.noContent().build();}}
